def calculate(a, op, b):
    if op == "+":
        return str(a + b)
    if op == "-":
        return str(a - b)
    if op == "*":
        return str(a * b)
    if op == "/" or op == "%":
        if b == 0:
            return "Error"
        if op == "/":
            return f"{a / b:.2f}"
        return str(a % b)
    return "Invalid operator"

