def luhn_valid(number):
    total = 0
    pos = 0
    for i in range(len(number) - 1, -1, -1):
        ch = number[i]
        if ch == " ":
            continue
        d = int(ch)
        if pos % 2 == 1:
            d = d * 2
            if d > 9:
                d -= 9
        total += d
        pos += 1
    return total % 10 == 0

card = input()
if luhn_valid(card):
    print("Valid")
else:
    print("Invalid")

